"components/core/include/core.hpp" to "#pragma once\n#include <cmath>\n#include <cstdint>\n#include \"esp_err.h\"\n#include \"freertos/FreeRTOS.h\"\n#include \"freertos/semphr.h\"\n\nstruct AxisCalibration { int minimum=1300, center=1500, maximum=1700; bool inverted=false; };\nstruct Calibration {\n    uint32_t version=1;\n    AxisCalibration x, y;\n    int lid_open=1500, lid_closed=1700;\n    bool lid_enabled=false;\n};\nenum class Mode { Manual, Random, Tracking };\nstruct EyeState {\n    Calibration calibration;\n    Mode mode=Mode::Manual;\n    float x=0, y=0, target_x=0, target_y=0, lid=0;\n    float smoothing=0.12f, speed=0.8f, deadband=0.08f;\n    bool armed=false, camera_requested=false, camera_ready=false, face=false;\n    float face_x=0, face_y=0;\n    int64_t face_time=0;\n    int64_t control_heartbeat=0;\n    esp_err_t camera_error=ESP_OK;\n};\nextern EyeState eye;\nextern SemaphoreHandle_t state_mutex;\nstruct StateLock {\n    StateLock() { xSemaphoreTakeRecursive(state_mutex, portMAX_DELAY); }\n    ~StateLock() { xSemaphoreGiveRecursive(state_mutex); }\n};\ninline float bounded(float value, float low=-1, float high=1) { return fminf(high, fmaxf(low,value)); }\n",
"components/eye_control/CMakeLists.txt" to "idf_component_register(SRCS \"eye_control.cpp\" INCLUDE_DIRS \"include\" REQUIRES core servo calibration tracking esp_hw_support)\n",
"components/eye_control/eye_control.cpp" to "#include \"eye_control.hpp\"\n#include \"core.hpp\"\n#include \"servo.hpp\"\n#include \"calibration.hpp\"\n#include \"tracking.hpp\"\n#include \"esp_random.h\"\n#include \"esp_timer.h\"\n#include \"esp_log.h\"\n#include \"freertos/task.h\"\nstatic void control_task(void *) {\n    TickType_t wake=xTaskGetTickCount();\n    int64_t next_random=0;\n    int64_t next_blink=0;\n    int64_t blink_started=-1;\n    int64_t next_servo_retry=0;\n    bool servo_available=false;\n    while(true) {\n        {\n            StateLock lock;\n            eye.control_heartbeat=esp_timer_get_time();\n            const int64_t now=eye.control_heartbeat;\n            if(eye.armed && eye.mode==Mode::Random && eye.calibration.lid_enabled) {\n                if(next_blink==0) next_blink=now+2000000+esp_random()%4000000;\n                if(blink_started<0 && now>=next_blink) blink_started=now;\n                if(blink_started>=0) {\n                    const int64_t elapsed=now-blink_started;\n                    if(elapsed<120000) eye.lid=static_cast<float>(elapsed)/120000;\n                    else if(elapsed<180000) eye.lid=1;\n                    else if(elapsed<360000) eye.lid=1-static_cast<float>(elapsed-180000)/180000;\n                    else {\n                        eye.lid=0;\n                        blink_started=-1;\n                        next_blink=now+2000000+esp_random()%4000000;\n                    }\n                } else eye.lid=fmaxf(0,eye.lid-0.1f);\n            } else {\n                next_blink=0;\n                blink_started=-1;\n            }\n            if (!servo_available && now >= next_servo_retry) {\n                const esp_err_t err=servo_init();\n                servo_available=(err==ESP_OK);\n                next_servo_retry=now+5000000;\n                if (servo_available) ESP_LOGI(\"eye_control\",\"PCA9685 connected; servo control available\");\n                else ESP_LOGW(\"eye_control\",\"PCA9685 unavailable (%s); retrying in 5s\",esp_err_to_name(err));\n            }\n            if(eye.armed) {\n                if(eye.mode==Mode::Random && esp_timer_get_time()>next_random) {\n                    eye.target_x=(static_cast<int>(esp_random()%1801)-900)/1000.0f;\n                    eye.target_y=(static_cast<int>(esp_random()%1401)-700)/1000.0f;\n                    next_random=esp_timer_get_time()+700000+esp_random()%2300000;\n                }\n                if(eye.mode==Mode::Tracking) tracking_update();\n                eye.x=tracking_step(eye.x,eye.target_x,eye.smoothing,eye.speed,0.02f);\n                eye.y=tracking_step(eye.y,eye.target_y,eye.smoothing,eye.speed,0.02f);\n                if (servo_available) {\n                    esp_err_t err=servo_write(0,calibration_pulse(eye.calibration.x,eye.x));\n                    if (err==ESP_OK) err=servo_write(1,calibration_pulse(eye.calibration.y,eye.y));\n                    if (err==ESP_OK && eye.calibration.lid_enabled)\n                        err=servo_write(2,lroundf(eye.calibration.lid_open+eye.lid*(eye.calibration.lid_closed-eye.calibration.lid_open)));\n                    else if (err==ESP_OK) servo_stop(2);\n                    if (err!=ESP_OK) {\n                        ESP_LOGW(\"eye_control\",\"PCA9685 communication lost (%s); disabling outputs\",esp_err_to_name(err));\n                        servo_available=false;\n                        next_servo_retry=now+5000000;\n                    }\n                }\n            } else if (servo_available) for(int channel=0;channel<3;channel++) servo_stop(channel);\n        }\n        vTaskDelayUntil(&wake,pdMS_TO_TICKS(20));\n    }\n}\nesp_err_t eye_control_start() {\n    return xTaskCreate(control_task,\"eye_control\",4096,nullptr,5,nullptr)==pdPASS ? ESP_OK : ESP_ERR_NO_MEM;\n}\n",
